INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'★★ *gathered the vine of the earth, and cast it into the great winepress of the wrath of Elohim (God)* (Revelation 14:19) — the nations *delivered... to the slaughter* (Isaiah 34:2) are the vine cast into the press.'
  FROM cross_reference_threads t
  JOIN _s303_isa34_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=2
  JOIN _s303_isa34_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='revelation' AND tv.chapter_number=14 AND tv.verse_number=19
