INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'★★ *When thou passest through the waters, I will be with thee... when thou walkest through the fire, thou shalt not be burned* (Isaiah 43:2) — the *I am with thee* of 41:10 unfolded; the presence that walks the servant through waters and fire.'
