INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 4, E'★★ *he hath said, I will never leave thee, nor forsake thee* (Hebrews 13:5) — the apostolic anchor of the *I am with thee... I will help thee* of Isaiah 41:10, the same word Moses spoke.'
  FROM cross_reference_threads t
