INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'★ *Yet I am Yahuah Elohayka (the LORD thy God) from the land of Egypt... for there is no saviour beside me* (Hosea 13:4) — the same declaration as *beside me there is no saviour* (Isaiah 43:11); Yahuah alone saves.'
